 31	// TestCapabilitiesAreOnlyReachedThroughHelpers fails when code type-asserts an
 32	// agent to an optional capability interface instead of calling its As* helper.
 33	//
 34	// An inline assertion skips the helper's DeclaredCaps gate, so an external
 35	// agent that implements the method but did not declare the capability is used
 36	// anyway. It also hides the capability from the DeclaredCaps doc list, which is
 37	// derived from the helpers.
 38	//
 39	// The check parses every production Go file rather than grepping it, so an
 40	// import under another name (agentpkg, cliagent) and a type-switch case list
 41	// that wraps onto a second line are both seen. Naming the package-agent
 42	// interface is not the only way to reach one, so an asserted type is also
 43	// followed through aliases, defined types, interface literals, and interfaces
 44	// declared in any repository package, and matched by the capability methods or
 45	// embedded capability interfaces it reaches.
 46	func TestCapabilitiesAreOnlyReachedThroughHelpers(t *testing.T) {
 47		t.Parallel()
 48	
 49		repoRoot, ok := testutil.GitGrepGuardRepoRoot(t)
 50		if !ok {
 51			return
 52		}
