 54		interfaces, helpers := agentPackageDecls(t)
 55		resolver := &assertionResolver{
 56			interfaces: interfaces,
 57			methods:    capabilityMethods(interfaces),
 58			decls:      map[string]map[string][]typeDecl{},
 59		}
 60	
 61		var files []*sourceFile
 62		fset := token.NewFileSet()
 63		for _, rel := range productionGoFiles(t, repoRoot) {
 64			src, err := os.ReadFile(filepath.Join(repoRoot, filepath.FromSlash(rel)))
 65			if errors.Is(err, fs.ErrNotExist) {
 66				// A tracked file deleted from the working tree or excluded by a
 67				// sparse checkout is not compiled here either; the checkout that
 68				// builds it runs this guard over it.
 69				t.Logf("skipping %s: %v", rel, err)
 70				continue
 71			}
 72			if err != nil {
 73				t.Fatalf("read %s: %v", rel, err)
 74			}
 75			parsed, err := parser.ParseFile(fset, rel, src, parser.SkipObjectResolution)
 76			if err != nil {
 77				// A file with a syntax error cannot compile either, so it cannot
 78				// hide an assertion; it is more likely an untracked scratch file.
 79				t.Logf("skipping %s: %v", rel, err)
