127	// sourceFile is a parsed production file and the names it uses for the
128	// packages it imports.
129	type sourceFile struct {
130		rel       string
131		dir       string
132		ast       *ast.File
133		qualifier string            // see agentImportName
134		imports   map[string]string // local package name to directory, for repository packages
