167	// assertionResolver follows an asserted type to the package-agent capability
168	// it reaches, if any.
169	type assertionResolver struct {
170		interfaces map[string]*ast.InterfaceType // package agent's interfaces
171		methods    map[string]string             // see capabilityMethods
172		// decls holds every named type by directory and name. A name can have
173		// several declarations when build-tagged files declare it differently.
174		decls map[string]map[string][]typeDecl
175	}
