248	// helperAdvice tells the developer how to reach capability through its As*
249	// helper, including how to add one when the capability has none yet.
250	func helperAdvice(capability string, helpers map[string]struct{}) string {
251		helper := "As" + capability
252		if _, ok := helpers[helper]; ok {
253			return "call " + helper + " so its DeclaredCaps gate applies"
254		}
255		return "add " + helper + " to package agent, resolving through declaredCapability (with a DeclaredCaps field), " +
256			"builtinCapability, or nonDeclarerCapability (listing " + capability + " in the DeclaredCaps doc for the last two), and call it"
257	}
