391	// productionGoFiles lists the repository's tracked and untracked Go files
392	// outside _test.go, slash-separated relative to repoRoot, with the same
393	// isolation as testutil.GitGrepGuard. -z keeps non-ASCII paths unquoted, since
394	// GuardGitEnv drops the caller's core.quotePath setting.
395	func productionGoFiles(t *testing.T, repoRoot string) []string {
396		t.Helper()
397	
398		cmd := exec.Command("git", "ls-files", "-z", "--cached", "--others", "--exclude-standard", "--", "*.go") //nolint:noctx // guard test, no cancellation needed
399		cmd.Dir = repoRoot
400		cmd.Env = testutil.GuardGitEnv()
401		out, err := cmd.Output()
402		if err != nil {
403			t.Fatalf("git ls-files: %v", err)
404		}
405		var files []string
406		for name := range strings.SplitSeq(string(out), "\x00") {
407			if name != "" && !strings.HasSuffix(name, "_test.go") {
408				files = append(files, name)
409			}
410		}
411		if len(files) == 0 {
412			t.Fatal("git ls-files found no Go files — the guard's file discovery has gone stale")
413		}
414		return files
415	}
416	
417	// agentPackageDecls returns the interfaces declared in the production files of
418	// package agent, by name, and the names of its package-level functions.
419	func agentPackageDecls(t *testing.T) (map[string]*ast.InterfaceType, map[string]struct{}) {
420		t.Helper()
421	
422		dir := findAgentDir(t)
423		fset := token.NewFileSet()
424		//nolint:staticcheck // ParseDir intentionally scans every production file regardless of build tags.
425		pkgs, err := parser.ParseDir(fset, dir, func(info os.FileInfo) bool {
426			return !strings.HasSuffix(info.Name(), "_test.go")
427		}, 0)
428		if err != nil {
429			t.Fatalf("parser.ParseDir(%s): %v", dir, err)
430		}
431	
432		interfaces := map[string]*ast.InterfaceType{}
433		funcs := map[string]struct{}{}
434		for _, pkg := range pkgs {
435			for _, file := range pkg.Files {
436				maps.Copy(interfaces, declaredInterfaces(file))
437				for _, decl := range file.Decls {
438					if funcDecl, ok := decl.(*ast.FuncDecl); ok && funcDecl.Recv == nil {
439						funcs[funcDecl.Name.Name] = struct{}{}
440					}
441				}
442			}
443		}
444		if len(interfaces) == 0 {
445			t.Fatal("no interfaces found in package agent — test setup is broken")
446		}
447		return interfaces, funcs
448	}

